INSERT INTO character_class (id, stable_key, name, description, hit_die, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured) VALUES (20, 'class.chevalier', 'Chevalier', 'Les Chevaliers sont des combattants formés à survivre au premier rang, là où les armures se brisent et où les héros tombent. Certains deviennent des Berserkers, sacrifiant leur propre chair et toute prudence pour déchaîner une violence toujours plus destructrice. D’autres suivent la voie du Rempart, utilisant leur bouclier, leur endurance et leur sens du sacrifice pour protéger leurs compagnons, intercepter les attaques et porter à leur place le poids de la bataille.', 10, 2, 0, 0, 0, 0, 0, 1);
INSERT INTO character_class (id, stable_key, name, description, hit_die, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured) VALUES (21, 'class.roublard', 'Roublard', 'Les Roublards survivent grâce à leur mobilité, leur précision et leur capacité à frapper là où l’adversaire est le plus vulnérable. L’Archer privilégie la maîtrise des armes à distance : il observe le terrain, ignore les protections et élimine ses cibles avant qu’elles puissent l’approcher. Le Voleur préfère les ombres, les mensonges et les ouvertures créées par ses alliés, utilisant feintes, attaques critiques et disparitions soudaines pour abattre un ennemi sans lui laisser l’occasion de riposter.', 8, 0, 2, 0, 0, 0, 0, 1);
INSERT INTO character_class (id, stable_key, name, description, hit_die, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured) VALUES (22, 'class.heraut', 'Héraut', 'Les Hérauts savent qu’une parole bien placée peut transformer une foule apeurée en armée ou faire vaciller un adversaire avant même que les armes soient tirées. Le Barde inspire ses alliés par ses chants, ses récits et sa présence, renforçant leur courage tout en accablant l’ennemi de doute. Le Diplomate impose sa volonté plus directement : meneur, négociateur ou tyran, il commande le champ de bataille, brise le moral adverse et pousse ses compagnons à agir au moment décisif.', 8, 0, 0, 0, 0, 0, 2, 1);
INSERT INTO character_class (id, stable_key, name, description, hit_die, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured) VALUES (23, 'class.specialiste', 'Spécialiste', 'Les Spécialistes ne dépendent ni des miracles ni d’un héritage surnaturel : leur force vient de leur préparation et de leur compréhension du monde. L’Ingénieur fabrique pièges, armes améliorées, canons et automates capables de rivaliser avec les créatures les plus imposantes. Le Survivaliste étudie plutôt les terrains et les proies, organisant les campements, révélant les faiblesses ennemies et guidant son groupe à travers les régions que nul voyageur ordinaire ne pourrait traverser.', 8, 0, 0, 0, 2, 0, 0, 1);
INSERT INTO character_class (id, stable_key, name, description, hit_die, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured) VALUES (24, 'class.clerc', 'Clerc', 'Les Clercs tirent leur pouvoir de la foi, des rites et des forces invisibles qui gouvernent les âmes. Le Prêtre reste fidèle aux miracles de lumière et de foudre transmis par les anciens dieux : il soigne les blessés, bénit les armes et invoque la puissance des cieux. L’Occultiste, au contraire, étudie l’Humanité, les Ténèbres et les arts interdits, drainant la vie ou réveillant les morts pour retourner contre le monde les forces qu’il cherche à comprendre.', 8, 0, 0, 0, 0, 2, 0, 1);
INSERT INTO character_class (id, stable_key, name, description, hit_die, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured) VALUES (25, 'class.sorcier', 'Sorcier', 'Les Sorciers cherchent à comprendre les lois qui se cachent derrière les âmes, les cristaux et les forces élémentaires. Le Chercheur poursuit la connaissance sous toutes ses formes, modifiant ses sorts, analysant les phénomènes magiques et retournant les sortilèges ennemis contre leurs auteurs. Le Cryomancien transforme cette maîtrise en contrôle de la glace : il ralentit les adversaires, façonne des outils ou des prisons gelées et finit par imposer autour de lui un domaine où le froid obéit à sa volonté.', 6, 0, 0, 0, 2, 0, 0, 1);
INSERT INTO character_class (id, stable_key, name, description, hit_die, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured) VALUES (26, 'class.pyromancien', 'Pyromancien', 'Les Pyromanciens manipulent une flamme intimement liée à la vie, à l’instinct et à la volonté de celui qui la porte. L’Adepte du Chaos embrasse l’héritage d’Izalith et transforme le terrain en brasier, répandant flammes et lave jusqu’à engloutir ses ennemis. Le Profane nourrit une flamme plus sombre avec sa propre vitalité : chaque sort devient un sacrifice capable de consumer non seulement les corps, mais également les émotions, les pouvoirs et jusqu’aux principes qui définissent ses victimes.', 8, 0, 0, 0, 0, 2, 0, 1);
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (10, 'Dieux', 'Les Dieux descendent des puissances qui fondèrent l’Âge du Feu après la guerre contre les Dragons. Leur nature leur offre une grande résistance physique et élémentaire, mais ne les protège ni des malédictions ni des atteintes portées directement à l’âme. Le Dieu solaire perpétue l’autorité lumineuse d’Anor Londo, maniant miracles, foudre et auras protectrices. Le Dieu occulte explore les secrets que les autres divinités préféreraient enterrer, utilisant péchés et malédictions comme instruments de connaissance et de jugement.', 'Les Chevaliers d’Argent seront une sous-race.', NULL, NULL, 2, 2, 0, 1, 'species.dieux');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (11, 'Humains', 'Les Humains portent en eux la puissance de l’Âme sombre, mais vivent sous la menace de la Malédiction des morts-vivants et du Carcassage. Le Mort-Vivant Élu choisit de préserver son lien avec le feu : il renforce les feux de camp, résiste aux Ténèbres et partage avec ses alliés la chaleur qui maintient leur volonté intacte. Le Porteur de la Malédiction accepte au contraire le Signe sombre et utilise son propre Carcassage comme une source de puissance, devenant plus dangereux à mesure que son humanité et son identité s’effritent.', 'En Carcassage : −2 Spirituelle.', NULL, NULL, 0, 0, 0, 1, 'species.humains');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (13, 'Géants', 'Les Géants sont des êtres d’une taille et d’une force prodigieuses, souvent réduits en esclavage, utilisés comme soldats ou oubliés au milieu des ruines d’anciens royaumes. Le Géant asservi descend des colosses employés par les seigneurs de Lordran : malgré ses chaînes, il maîtrise les arcs gigantesques, les projectiles de siège et le lancer d’armes lourdes avec une précision terrifiante. Le Géant-arbre appartient aux lignées anciennes de Drangleic, dont les corps noueux ressemblent à des troncs vivants : extrêmement vulnérable au feu, il possède en contrepartie une force physique inégalée, capable de renverser murailles et créatures colossales.', 'Extrêmement robustes, mais sensibles aux forces élémentaires.', NULL, NULL, 3, -2, 0, 1, 'species.geants');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (16, 'Gyrm', 'Les Gyrm sont un peuple trapu et robuste, habitué aux profondeurs, à la pierre et aux mécanismes complexes. Le Gardien du Roc transforme cette endurance en protection absolue, refusant de céder du terrain et encaissant les coups destinés à ses alliés. Le Maître des Forges perpétue le savoir artisanal de son peuple, réparant les constructions, améliorant les armes et créant des équipements capables de conserver durablement une puissance élémentaire.', 'Nains robustes et résistants.', NULL, NULL, 2, 0, 0, 1, 'species.gyrm');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (17, 'Clan du Lion', 'Les membres du Clan du Lion sont des guerriers félins originaire de Forossa dont le corps résiste naturellement aux forces surnaturelles. La Crinière noble représente les anciennes lignées martiales : disciplinée, fière et précise, elle perfectionne plusieurs familles d’armes jusqu’à atteindre une maîtrise presque parfaite. Le Fauve de guerre abandonne cette retenue pour retrouver l’instinct du prédateur, bondissant sur ses ennemis et les déchirant dans une succession d’attaques rapides.', 'Résistance générale aux forces magiques.', NULL, NULL, 0, 2, 2, 1, 'species.clan-du-lion');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (18, 'Corviens', 'Les Corviens sont des êtres fragiles, mais dotés d’une perception aiguë et d’une affinité particulière avec les hauteurs, les secrets et les péchés. Le Confesseur de Velka sert la déesse du péché : il révèle les fautes cachées, marque les coupables et transforme leur culpabilité en faiblesse. Le Rapace des Cimes développe pleinement ses ailes et ses instincts d’oiseau de proie, observant le monde depuis les hauteurs avant de fondre sur sa cible.', 'Fragiles physiquement ; leurs ailes évoluent avec eux.', NULL, NULL, -2, 0, 2, 1, 'species.corviens');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (21, 'Hommes-Serpents', 'Les Hommes-Serpents sont des descendants imparfaits ou éloignés des Dragons antiques. Le Serpent quadribrachial développe une morphologie guerrière dotée de plusieurs bras, lui permettant de saisir plusieurs adversaires ou de manier un véritable arsenal. Le Serpent-oracle cultive plutôt l’héritage mystique du serpent et du dragon, utilisant venin, hypnose, mues surnaturelles et visions prophétiques pour contrôler ses ennemis.', 'Guerriers robustes possédant une morsure venimeuse.', NULL, NULL, 2, 0, -2, 1, 'species.hommes-serpents');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (22, 'Hommes-champignons', 'Les Hommes-champignons sont des êtres fongiques anciens, généralement paisibles jusqu’à ce que leur territoire ou leur réseau soit menacé. Le Fongique ancestral est une créature massive qui s’enracine dans le sol pour devenir presque impossible à déplacer, avant de répondre par des coups d’une force écrasante. Le Mycélien sporifère agit comme une partie consciente d’un organisme collectif : ses spores permettent de communiquer, de soigner ses alliés, d’empoisonner ses ennemis et de relier plusieurs créatures au sein d’un même réseau vivant.', 'Dépendra de la future voie choisie.', NULL, NULL, 3, -2, 0, 1, 'species.hommes-champignons');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (23, 'Démons', 'Les Démons sont des créatures transformées par les puissances instables issues d’Izalith, mais tous n’acceptent pas de la même manière l’héritage du Chaos. Le Démon de Feu incarne la forme démoniaque la plus connue : une créature brutale dont le corps brûlant alimente des explosions, des souffles ardents et des pyromancies destructrices. Le Démon de Pierre a rejeté la corruption du Chaos et discipliné sa flamme jusqu’à la rendre dense et minérale, façonnant roche, lave refroidie et carapaces de pierre grâce à des pyromancies anciennes.', 'Réunit les Démons, Filles du Chaos et descendants Ghru.', NULL, NULL, 0, 3, -2, 1, 'species.demons');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (25, 'Dragons', 'Les Dragons portent les traces d’un monde antérieur à la distinction entre la lumière et les ténèbres. Puissants contre les attaques physiques et élémentaires, ils restent cependant vulnérables aux forces qui s’en prennent directement à l’âme. Le Dragon ancestral cultive la puissance des Dragons antiques : ses écailles s’épaississent, ses ailes grandissent et son souffle devient capable de ravager des groupes entiers. Le Dragon cristallin suit l’héritage de Seath, remplaçant l’immuabilité des anciens Dragons par la sorcellerie, la régénération et la perfection minérale du cristal.', 'Leur souffle et leur capacité de vol évolueront plus tard.', NULL, NULL, 2, 3, -2, 1, 'species.dragons');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (26, 'Demi-Humains', 'Les Demi-Humains sont des chimères dont le corps et l’esprit demeurent étonnamment adaptables. La Chimère férale accepte son héritage animal et développe griffes, sens aiguisés, mobilité et instincts de chasse, devenant progressivement un prédateur complet. La Chimère éveillée privilégie l’intelligence et l’imitation : elle observe les autres peuples, reproduit leurs talents et réorganise ses propres capacités selon les obstacles rencontrés.', 'Chimères capables d’évoluer selon leur voie.', NULL, NULL, 0, 0, 0, 1, 'species.demi-humains');
INSERT INTO species (id, name, description, traits, size, speed, physical_bonus, elemental_bonus, spiritual_bonus, configured, stable_key) VALUES (28, 'Enfant des Ténèbres', 'Les Enfants des Ténèbres proviennent de puissances nées dans les profondeurs du monde, mais leur nature dépend de leur origine. L’Enfant de la Mort appartient à l’héritage de Nito : son corps ne fonctionne plus comme celui d’un vivant, se reconstitue après les blessures et peut rappeler temporairement les cadavres au combat. L’Enfant des Abysses porte une parcelle de l’obscurité déchaînée : sa chair se déforme, ses membres s’allongent et ses mutations le rapprochent peu à peu d’une bête monstrueuse.', 'Choisissez une origine : Enfant de la Mort ou Enfant des Abysses.', NULL, NULL, 0, 0, 0, 1, 'species.enfant-des-tenebres');
