INSERT INTO class_path (id, class_id, name, abilities, ranks_json, configured, stable_key) VALUES (2, 20, 'Berserker', 'FOR', '[{"rank": 1, "name": "Fureur écarlate", "active": {"timing": "Action bonus", "uses": "2 fois par repos court", "effect": "Le personnage ajoute 1d6 dégâts à sa prochaine attaque une fois par tour pendant 3 tours. Le personnage augmente sa Défense physique de -2 pendant 3 tours. Le personnage augmente sa Défense élémentaire de -2 pendant 3 tours. Le personnage augmente sa Défense spirituelle de -2 pendant 3 tours. 2 utilisations, récupérées après un repos court.", "activation": {"type": "bonus_action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["short_rest"], "id": "path.chevalier.berserker.rank-1.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.chevalier.berserker.rank-1", "capabilities": [{"id": "path.chevalier.berserker.rank-1.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "damage", "target": "selected", "damage_type": "inherited", "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}, "frequency": "once_per_turn", "duration": {"value": 3, "unit": "turn"}, "mode": "attach"}, {"type": "modify_stat", "target": "selected", "stat": "defense.physical", "value": -2, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}, {"type": "modify_stat", "target": "selected", "stat": "defense.elemental", "value": -2, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}, {"type": "modify_stat", "target": "selected", "stat": "defense.spiritual", "value": -2, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}], "uses": {"maximum": 2, "recharge": "short_rest"}}]}, {"rank": 2, "name": "Offrande de sang", "active": {"timing": "Libre", "uses": "3 fois par Repos au Feu", "effect": "Le personnage subit 1d6 dégâts. Le personnage ajoute 2d6 dégâts à sa prochaine attaque. 3 utilisations, récupérées après un repos long.", "activation": {"type": "free"}, "resource": {"maximum": 3, "cost": 1, "recovery": ["long_rest"], "id": "path.chevalier.berserker.rank-2.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.chevalier.berserker.rank-2", "capabilities": [{"id": "path.chevalier.berserker.rank-2.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "damage", "target": "self", "bypass_defense": true, "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}}, {"type": "damage", "target": "selected", "damage_type": "inherited", "value": {"dice": {"count": 2, "sides": 6}, "terms": [], "constant": 0}, "frequency": "next_attack", "mode": "attach"}], "uses": {"maximum": 3, "recharge": "long_rest"}}]}, {"rank": 3, "name": "Refus de mourir", "active": {"timing": "Réaction", "uses": "1 fois par Repos au Feu", "effect": "Le personnage reste à au moins 1 PV au lieu de tomber à 0 PV. Le personnage ajoute 1d6 dégâts à sa prochaine attaque pendant 2 tours. Une utilisation, récupérée après un repos long.", "activation": {"type": "reaction"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.chevalier.berserker.rank-3.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.chevalier.berserker.rank-3", "capabilities": [{"id": "path.chevalier.berserker.rank-3.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_resource", "target": "selected", "value": 1, "resource": "health", "operation": "set_minimum"}, {"type": "damage", "target": "selected", "damage_type": "inherited", "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}, "frequency": "each_attack", "duration": {"value": 2, "unit": "turn"}, "mode": "attach"}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Tourbillon carnassier", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Attaque tous les ennemis adjacents : dégâts 