INSERT INTO class_path (id, class_id, name, abilities, ranks_json, configured, stable_key) VALUES (3, 21, 'Voleur', 'DEX + CHA', '[{"rank": 1, "name": "Pas de l’ombre", "active": null, "passive": {"frequency": "Permanent", "effect": "Ajoutez +2 au résultat de vos tests de Discrétion, Tromperie et Escamotage, ainsi qu’aux tests effectués avec des outils de voleur. Vous pouvez effectuer l’action Se cacher avec une action bonus.", "automation": {"level": "partial", "effects": []}}, "id": "path.roublard.voleur.rank-1", "capabilities": [{"id": "path.roublard.voleur.rank-1.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Ajoutez +2 au résultat de vos tests de Discrétion, Tromperie et Escamotage, ainsi qu’aux tests effectués avec des outils de voleur. Vous pouvez effectuer l’action Se cacher avec une action bonus."}]}]}, {"rank": 2, "name": "Frappe déloyale", "active": null, "passive": {"frequency": "1/tour", "effect": "Une attaque contre une cible surprise, distraite ou engagée par un allié inflige +2d6 dégâts.", "automation": {"level": "partial", "effects": []}}, "id": "path.roublard.voleur.rank-2", "capabilities": [{"id": "path.roublard.voleur.rank-2.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Une attaque contre une cible surprise, distraite ou engagée par un allié inflige +2d6 dégâts."}]}]}, {"rank": 3, "name": "Feinte fatale", "active": {"timing": "Action bonus", "uses": "2 fois par repos court", "effect": "Feinte : la cible perd 2 Défense physique et la prochaine attaque du Voleur devient critique.", "activation": {"type": "bonus_action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["short_rest"], "id": "path.roublard.voleur.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.roublard.voleur.rank-3", "capabilities": [{"id": "pa