vation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.clerc.occultiste.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.clerc.occultiste.rank-3", "capabilities": [{"id": "path.clerc.occultiste.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Anime un cadavre pendant 5 tours : 20 PV, Défenses 4/2/4 et attaque de 2d6 + MOD Sagesse."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Rituel du néant", "active": {"timing": "Action bonus", "uses": "1 fois par Repos au Feu", "effect": "Forme d’Humanité pendant 5 tours : +2 Défense spirituelle, drain de 1d6 PV par tour et reste à 1 PV la première fois qu’il tombe à 0.", "activation": {"type": "bonus_action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.clerc.occultiste.rank-4.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.clerc.occultiste.rank-4", "capabilities": [{"id": "path.clerc.occultiste.rank-4.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Forme d’Humanité pendant 5 tours : +2 Défense spirituelle, drain de 1d6 PV par tour et reste à 1 PV la première fois qu’il tombe à 0."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Pacte ultime", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Chaque ennemi situé dans un rayon de 6 m subit 5d6 dégâts de Ténèbres. Une sauvegarde de Sagesse réussie réduit ces dégâts de moitié. Choisissez ensuite un seul effet : vous récupérez un nombre de PV égal au total des dégâts infligés, avec un maximum de 5d6 PV, ou vous animez jusqu’à trois cadavres.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.clerc.occultiste.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.clerc.occultiste.rank-5", "capabilities": [{"id": "path.clerc.occultiste.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Chaque ennemi situé dans un rayon de 6 m subit 5d6 dégâts de Ténèbres. Une sauvegarde de Sagesse réussie réduit ces dégâts de moitié. Choisissez ensuite un seul effet : vous récupérez un nombre de PV égal au total des dégâts infligés, avec un maximum de 5d6 PV, ou vous animez jusqu’à trois cadavres."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 1, 'path.clerc.occultiste');
INSERT INTO class_path (id, class_id, name, abilities, ranks_json, configured, stable_key) VALUES (11, 25, 'Cryomancien', 'INT + SAG', '[{"rank": 1, "name": "Morsure du givre", "active": {"timing": "Action", "uses": "3 fois par Repos au Feu", "effect": "La cible ennemie subit 2d6 + modificateur d’Intelligence dégâts de glace. La cible ennemie augmente sa vitesse de déplacement de -3 pendant 2 tours. 3 utilisations, récupérées après un repos long.", "activation": {"type": "action"}, "resource": {"maximum": 3, "cost": 1, "recovery": ["long_rest"], "id": "path.sorcier.cryomancien.rank-1.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.sorcier.cryomancien.rank-1", "capabilities": [{"id": "path.sorcier.cryomancien.rank-1.active", "support": "full", "targeting": {"selector": "single", "allegiance": ["enemy"]}, "operations": [{"type": "damage", "target": "selected", "damage_type": "ice", "value": {"dice": {"count": 2, "sides": 6}, "terms": [{"type": "ability_modifier", "ability": "intelligence"}], "constant": 0}}, {"type": "modify_stat", "target": "selected", "stat": "movement.speed", "value": -3, "duration": {"value": 2, "unit": "turn"}, "operation": "add"}], "uses": {"maximum": 3, "recharge": "long_rest"}}]}, {"rank": 2, "name": "Miroir de givre", "active": {"timing": "Réaction", "uses": "2 fois par Repos au Feu", "effect": "Le personnage réduit les dégâts reçus de 1d8 + modificateur d’Intelligence. 2 utilisations, récupérées après un repos long.", "activation": {"type": "reaction"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.sorcier.cryomancien.rank-2.uses"}, "automation": {"level": "full", "effects": []}}, "passive": {"frequency": "À volonté", "effect": "Vous pouvez façonner un petit objet utilitaire en glace, comme une clé simple, un récipient ou un outil. L’objet fond lorsque vous le décidez ou au prochain Repos au Feu et ne peut pas servir d’arme.", "automation": {"level": "partial", "effects": []}}, "id": "path.sorcier.cryomancien.rank-2", "capabilities": [{"id": "path.sorcier.cryomancien.rank-2.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_protection", "target": "selected", "value": {"dice": {"count": 1, "sides": 8}, "terms": [{"type": "ability_modifier", "ability": "intelligence"}], "constant": 0}}], "uses": {"maximum": 2, "recharge": "long_rest"}}, {"id": "path.sorcier.cryomancien.rank-2.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Vous pouvez façonner un petit objet utilitaire en glace, comme une clé simple, un récipient ou un outil. L’objet fond lorsque vous le décidez ou au prochain Repos au Feu et ne peut pas servir d’arme."}]}]}, {"rank": 3, "name": "Prison de glace", "active": {"timing": "Action", "uses": "2 fois par Repos au Feu", "effect": "Choisissez un seul effet : créer un mur de glace possédant 25 PV ; ou enfermer une cible dans une prison de glace. La cible effectue une sauvegarde de Force : en cas d’échec, elle est Immobilisée pendant 3 tours et subit 1d6 dégâts de Glace au début de chacun de ses tours ; en cas de réussite, la prison ne se forme pas.", "activation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.sorcier.cryomancien.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.sorcier.cryomancien.rank-3", "capabilities": [{"id": "path.sorcier.cryomancien.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Choisissez un seul effet : créer un mur de glace possédant 25 PV ; ou enfermer une cible dans une prison de glace. La cible effectue une sauvegarde de Force : en cas d’échec, elle est Immobilisée pendant 3 tours et subit 1d6 dégâts de Glace au début de chacun de ses tours ; en cas de réussite, la prison ne se forme pas."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Blizzard blanc", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Créez un blizzard dans un rayon de 6 m. Chaque créature dans la zone subit 5d6 + MOD Intelligence dégâts de Glace. Une sauvegarde de Dextérité réussie réduit ces dégâts de moitié. La zone devient un terrain difficile pendant 3 tours : chaque mètre parcouru y coûte 2 m de déplacement.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.sorcier.cryomancien.rank-4.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.sorcier.cryomancien.rank-4", "capabilities": [{"id": "path.sorcier.cryomancien.rank-4.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Créez un blizzard dans un rayon de 6 m. Chaque créature dans la zone subit 5d6 + MOD Intelligence dégâts de Glace. Une sauvegarde de Dextérité réussie réduit ces dégâts de moitié. La zone devient un terrain difficile pendant 3 tours : chaque mètre parcouru y coûte 2 m de déplacement."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Zéro absolu", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Les cibles dans la zone subit 2d6 dégâts de glace pendant 5 tours. Les cibles dans la zone augmente sa Défense élémentaire de -2 pendant 5 tours. Les cibles dans la zone multiplie sa vitesse de déplacement de +0 pendant 5 tours. Une utilisation, récupérée après un repos long.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.sorcier.cryomancien.rank-5.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.sorcier.cryomancien.rank-5", "capabilities": [{"id": "path.sorcier.cryomancien.rank-5.active", "support": "full", "targeting": {"selector": "all", "area": {"shape": "radius", "distance": {"value": 6, "unit": "meter"}}}, "operations": [{"type": "damage", "target": "selected", "damage_type": "ice", "value": {"dice": {"count": 2, "sides": 6}, "terms": [], "constant": 0}, "triggers": ["each_turn"], "duration": {"value": 5, "unit": "turn"}}, {"type": "modify_stat", "target": "selected", "stat": "defense.elemental", "value": -2, "duration": {"value": 5, "unit": "turn"}, "operation": "add"}, {"type": "modify_stat", "target": "selected", "stat": "movement.speed", "factor": 0.5, "duration": {"value": 5, "unit": "turn"}, "operation": "multiply", "value": 0}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 1, 'path.sorcier.cryomancien');
