ity", "target": "self", "description": "Chaque créature située dans un rayon de 4 m subit 6d6 + MOD Sagesse dégâts de Feu. Une sauvegarde de Dextérité réussie réduit ces dégâts de moitié. La zone reste couverte de lave pendant 2 tours."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Soleil du Chaos", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Tempête pendant 5 tours : zone de 6 m, 3d6 Feu par tour ; les alliés choisis gagnent +1d6 Feu une fois par tour.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.pyromancien.adepte-du-chaos.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.pyromancien.adepte-du-chaos.rank-5", "capabilities": [{"id": "path.pyromancien.adepte-du-chaos.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Tempête pendant 5 tours : zone de 6 m, 3d6 Feu par tour ; les alliés choisis gagnent +1d6 Feu une fois par tour."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 1, 'path.pyromancien.adepte-du-chaos');
INSERT INTO class_path (id, class_id, name, abilities, ranks_json, configured, stable_key) VALUES (14, 26, 'Profane', 'SAG + CON', '[{"rank": 1, "name": "Flamme noire", "active": {"timing": "Action", "uses": "3 fois par Repos au Feu", "effect": "Le personnage subit 1d6 dégâts. La cible ennemie subit 4d6 + modificateur de Sagesse dégâts de Ténèbres. 3 utilisations, récupérées après un repos long.", "activation": {"type": "action"}, "resource": {"maximum": 3, "cost": 1, "recovery": ["long_rest"], "id": "path.pyromancien.profane.rank-1.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.pyromancien.profane.rank-1", "capabilities": [{"id": "path.pyromancien.profane.rank-1.active", "support": "full", "targeting": {"selector": "single", "allegiance": ["enemy"]}, "operations": [{"type": "damage", "target": "self", "bypass_defense": true, "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}}, {"type": "damage", "target": "selected", "damage_type": "dark", "value": {"dice": {"count": 4, "sides": 6}, "terms": [{"type": "ability_modifier", "ability": "wisdom"}], "constant": 0}}], "uses": {"maximum": 3, "recharge": "long_rest"}}]}, {"rank": 2, "name": "Souillure ardente", "active": {"timing": "Action", "uses": "2 fois par Repos au Feu", "effect": "Perd 2d6 PV, inflige 5d6 + MOD Sagesse Ténèbres et récupère la moitié des dégâts réellement infligés.", "activation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.pyromancien.profane.rank-2.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.pyromancien.profane.rank-2", "capabilities": [{"id": "path.pyromancien.profane.rank-2.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Perd 2d6 PV, inflige 5d6 + MOD Sagesse Ténèbres et récupère la moitié des dégâts réellement infligés."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 3, "name": "Cendre maudite", "active": {"timing": "Action", "uses": "2 fois par Repos au Feu", "effect": "Perd 2d8 PV, inflige 4d6 Ténèbres et brûle une émotion pendant 3 tours si la sauvegarde de Sagesse échoue.", "activation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.pyromancien.profane.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.pyromancien.profane.rank-3", "capabilities": [{"id": "path.pyromancien.profane.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Perd 2d8 PV, inflige 4d6 Ténèbres et brûle une émotion pendant 3 tours si la sauvegarde de Sagesse échoue."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Bûcher profané", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Perd la moitié de ses PV actuels, inflige 8d6 + MOD Sagesse et bloque soin, déplacement, réaction ou une magie pendant 2 tours.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.pyromancien.profane.rank-4.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.pyromancien.profane.rank-4", "capabilities": [{"id": "path.pyromancien.profane.rank-4.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Perd la moitié de ses PV actuels, inflige 8d6 + MOD Sagesse et bloque soin, déplacement, réaction ou une magie pendant 2 tours."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Éclipse incendiaire", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Tombe à 1 PV et inflige 10d6 + MOD Sagesse. Sagesse ratée : un concept simple est supprimé pendant 5 tours ; réussite : moitié des dégâts seulement.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.pyromancien.profane.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.pyromancien.profane.rank-5", "capabilities": [{"id": "path.pyromancien.profane.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Tombe à 1 PV et inflige 10d6 + MOD Sagesse. Sagesse ratée : un concept simple est supprimé pendant 5 tours ; réussite : moitié des dégâts seulement."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 1, 'path.pyromancien.profane');
INSERT INTO racial_path (id, species_id, name, abilities, ranks_json, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured, stable_key, physical_bonus, elemental_bonus, spiritual_bonus) VALUES (1, 10, 'Dieu solaire', '+2 CHA, +1 SAG', '[{"rank": 1, "name": "Héritage solaire", "active": null, "passive": {"frequency": "Permanent", "effect": "Vous pouvez produire une lumière à volonté. Ajoutez +2 au résultat des tests sociaux servant à donner un ordre, imposer votre autorité ou impressionner par votre statut.", "automation": {"level": "partial", "effects": []}}, "id": "path.dieux.dieu-solaire.rank-1", "capabilities": [{"id": "path.dieux.dieu-solaire.rank-1.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Vous pouvez produire une lumière à volonté. Ajoutez +2 au résultat des tests sociaux servant à donner un ordre, imposer votre autorité ou impressionner par votre statut."}]}]}, {"rank": 2, "permanent_bonuses": {"elemental_defense": 2}, "name": "Rayon bienveillant", "active": null, "passive": {"frequency": "Permanent", "effect": "Le personnage augmente sa Défense élémentaire de +2.", "automation": {"level": "full", "effects": []}}, "id": "path.dieux.dieu-solaire.rank-2", "capabilities": [{"id": "path.dieux.dieu-solaire.rank-2.passive", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_stat", "target": "selected", "stat": "defense.elemental", "value": 2, "operation": "add"}]}]}, {"rank": 3, "name": "Couronne de lumière", "active": {"timing": "Action", "uses": "2 fois par Repos au Feu", "effect": "La cible ennemie subit 3d6 + modificateur de Sagesse dégâts de foudre. 2 utilisations, récupérées après un repos long.", "activation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.dieux.dieu-solaire.rank-3.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.dieux.dieu-solaire.rank-3", "capabilities": [{"id": "path.dieux.dieu-solaire.rank-3.active", "support": "full", "targeting": {"selector": "single", "allegiance": ["enemy"]}, "operations": [{"type": "damage", "target": "selected", "damage_type": "lightning", "value": {"dice": {"count": 3, "sides": 6}, "terms": [{"type": "ability_modifier", "ability": "wisdom"}], "constant": 0}}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Domaine radieux", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Les cibles dans la zone alliée augmente sa Défense physique de +1 pendant 3 tours. Les cibles dans la zone alliée augmente sa Défense élémentaire de +1 pendant 3 tours. Les cibles dans la zone alliée augmente sa Défense spirituelle de +1 pendant 3 tours. Les cibles dans la zone alliée ajoute 1d6 dégâts de lumière à sa prochaine attaque une fois par tour pendant 3 tours. Une utilisation, récupérée après un repos long.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.dieux.dieu-solaire.rank-4.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.dieux.dieu-solaire.rank-4", "capabilities": [{"id": "path.dieux.dieu-solaire.rank-4.active", "support": "full", "targeting": {"selector": "all", "allegiance": ["ally"], "include_self": false, "area": {"shape": "radius", "distance": {"value": 6, "unit": "meter"}}}, "operations": [{"type": "modify_stat", "target": "selected", "stat": "defense.physical", "value": 1, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}, {"type": "modify_stat", "target": "selected", "stat": "defense.elemental", "value": 1, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}, {"type": "modify_stat", "target": "selected", "stat": "defense.spiritual", "value": 1, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}, {"type": "damage", "target": "selected", "damage_type": "light", "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}, "frequency": "once_per_turn", "duration": {"value": 3, "unit": "turn"}, "mode": "attach"}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Avatar du soleil", "active": {"timing": "Action bonus", "uses": "1 fois par Repos au Feu", "effect": "Le personnage augmente sa Défense élémentaire de +2 pendant 5 tours. Le personnage augmente sa Défense spirituelle de +2 pendant 5 tours. Le personnage choisit entre plusieurs effets. Une utilisation, récupérée après un repos long.", "activation": {"type": "bonus_action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.dieux.dieu-solaire.rank-5.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.dieux.dieu-solaire.rank-5", "capabilities": [{"id": "path.dieux.dieu-solaire.rank-5.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_stat", "target": "selected", "stat": "defense.elemental", "value": 2, "duration": {"value": 5, "unit": "turn"}, "operation": "add"}, {"type": "modify_stat", "target": "selected", "stat": "defense.spiritual", "value": 2, "duration": {"value": 5, "unit": "turn"}, "operation": "add"}, {"type": "choice", "target": "selected", "id": "damage_type", "options": [{"id": "lightning", "label": "Foudre", "operations": [{"type": "damage", "target": "self", "damage_type": "lightning", "value": {"dice": {"count": 2, "sides": 6}, "terms": [], "constant": 0}, "frequency": "once_per_turn", "duration": {"value": 5, "unit": "turn"}, "mode": "attach"}]}, {"id": "light", "label": "Lumière", "operations": [{"type": "damage", "target": "self", "damage_type": "light", "value": {"dice": {"count": 2, "sides": 6}, "terms": [], "constant": 0}, "frequency": "once_per_turn", "duration": {"value": 5, "unit": "turn"}, "mode": "attach"}]}]}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 0, 0, 0, 0, 1, 2, 1, 'path.dieux.dieu-solaire', 0, 0, 0);
INSERT INTO racial_path (id, species_id, name, abilities, ranks_json, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured, stable_key, physical_bonus, elemental_bonus, spiritual_bonus) VALUES (2, 10, 'Dieu occulte', '+2 SAG, +1 INT', '[{"rank": 1, "name": "Héritage obscur", "active": null, "passive": {"frequency": "Permanent", "effect": "Vous ajoutez +2 au résultat des tests d’Intelligence portant sur les connaissances interdites. Vous détectez également la présence d’un péché ou d’une malédiction sur une créature située à 9 m ou moins, sans en apprendre automatiquement la nature.", "automation": {"level": "partial", "effects": []}}, "id": "path.dieux.dieu-occulte.rank-1", "capabilities": [{"id": "path.dieux.dieu-occulte.rank-1.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Vous ajoutez +2 au résultat des tests d’Intelligence portant sur les connaissances interdites. Vous détectez également la présence d’un péché ou d’une malédiction sur une créature située à 9 m ou moins, sans en apprendre automatiquement la nature."}]}]}, {"rank": 2, "name": "Voile du secret", "active": null, "passive": {"frequency": "1/tour", "effect": "Une fois par attaque, ajoutez 1d6 dégâts spirituels si la cible est affectée par une malédiction ou si sa culpabilité a été révélée par une de vos compétences.", "automation": {"level": "partial", "effects": []}}, "id": "path.dieux.dieu-occulte.rank-2", "capabilities": [{"id": "path.dieux.dieu-occulte.rank-2.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Une fois par attaque, ajoutez 1d6 dégâts spirituels si la cible est affectée par une malédiction ou si sa culpabilité a été révélée par une de vos compétences."}]}]}, {"rank": 3, "name": "Marque occulte", "active": {"timing": "Action", "uses": "2 fois par Repos au Feu", "effect": "La cible ennemie augmente sa Défense spirituelle de -2 pendant 3 tours. La cible ennemie augmente ses jets de sauvegarde de -2 pendant 3 tours. 2 utilisations, récupérées après un repos long.", "activation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.dieux.dieu-occulte.rank-3.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.dieux.dieu-occulte.rank-3", "capabilities": [{"id": "path.dieux.dieu-occulte.rank-3.active", "support": "full", "targeting": {"selector": "single", "allegiance": ["enemy"]}, "operations": [{"type": "modify_stat", "target": "selected", "stat": "defense.spiritual", "value": -2, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}, {"type": "modify_stat", "target": "selected", "stat": "saving_throw.all", "value": -2, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Domaine des ombres", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Révèle une cible pendant 5 tours : elle ne peut se cacher et les alliés ignorent 2 Défense spirituelle.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.dieux.dieu-occulte.rank-4.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.dieux.dieu-occulte.rank-4", "capabilities": [{"id": "path.dieux.dieu-occulte.rank-4.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Révèle une cible pendant 5 tours : elle ne peut se cacher et les alliés ignorent 2 Défense spirituelle."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Jugement nocturne", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Jugement de 6d6 + MOD Sagesse dégâts spirituels ; ajoute +1d6 par malédiction active, maximum +3d6.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.dieux.dieu-occulte.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.dieux.dieu-occulte.rank-5", "capabilities": [{"id": "path.dieux.dieu-occulte.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Jugement de 6d6 + MOD Sagesse dégâts spirituels ; ajoute +1d6 par malédiction active, maximum +3d6."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 0, 0, 0, 1, 2, 0, 1, 'path.dieux.dieu-occulte', 0, 0, 0);
