se.", "activation": {"type": "bonus_action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.gyrm.maitre-des-forges.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.gyrm.maitre-des-forges.rank-3", "capabilities": [{"id": "path.gyrm.maitre-des-forges.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Équipement amélioré pendant 3 tours : +1d6 dégâts une fois par tour ou +2 à une Défense."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Forge de guerre", "active": {"timing": "Rituel", "uses": "1 fois par Repos au Feu", "effect": "Ajoute jusqu’au prochain repos un élément et +1d6 dégâts une fois par tour à une arme.", "activation": {"type": "special"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.gyrm.maitre-des-forges.rank-4.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.gyrm.maitre-des-forges.rank-4", "capabilities": [{"id": "path.gyrm.maitre-des-forges.rank-4.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Ajoute jusqu’au prochain repos un élément et +1d6 dégâts une fois par tour à une arme."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Œuvre magistrale", "active": {"timing": "Rituel", "uses": "1 fois par Repos au Feu", "effect": "Crée un chef-d’œuvre possédant deux améliorations de rang 3 ou une amélioration de rang 4.", "activation": {"type": "special"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.gyrm.maitre-des-forges.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.gyrm.maitre-des-forges.rank-5", "capabilities": [{"id": "path.gyrm.maitre-des-forges.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Crée un chef-d’œuvre possédant deux améliorations de rang 3 ou une amélioration de rang 4."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 1, 0, 0, 2, 0, 0, 1, 'path.gyrm.maitre-des-forges', 0, 0, 0);
