 ["short_rest"], "id": "path.gyrm.gardien-du-roc.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.gyrm.gardien-du-roc.rank-3", "capabilities": [{"id": "path.gyrm.gardien-du-roc.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Intercepte entièrement une attaque visant un allié adjacent."}], "uses": {"maximum": 2, "recharge": "short_rest"}}]}, {"rank": 4, "name": "Cœur de montagne", "active": null, "passive": {"frequency": "Permanent", "effect": "Immunité aux déplacements forcés et +2 aux sauvegardes contre renversement et saisie.", "automation": {"level": "partial", "effects": []}}, "id": "path.gyrm.gardien-du-roc.rank-4", "capabilities": [{"id": "path.gyrm.gardien-du-roc.rank-4.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Immunité aux déplacements forcés et +2 aux sauvegardes contre renversement et saisie."}]}]}, {"rank": 5, "name": "Roc éternel", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Pendant 5 tours, vos alliés situés à 3 m ou moins gagnent +2 en Défense physique. Après application de leur Défense, ils ne subissent que la moitié des dégâts reçus et vous perdez autant de PV que les dégâts évités.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.gyrm.gardien-du-roc.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.gyrm.gardien-du-roc.rank-5", "capabilities": [{"id": "path.gyrm.gardien-du-roc.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Pendant 5 tours, vos alliés situés à 3 m ou moins gagnent +2 en Défense physique. Après application de leur Défense, ils ne subissent que la moitié des dégâts reçus et vous perdez autant de PV que les dégâts évités."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 1, 0, 2, 0, 0, 0, 1, 'path.gyrm.gardien-du-roc', 0, 0, 0);
