nk-4", "capabilities": [{"id": "path.dragons.dragon-cristallin.rank-4.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_protection", "target": "self", "reflect": true, "value": {"dice": {"count": 3, "sides": 8}, "terms": [{"type": "ability_modifier", "ability": "intelligence"}], "constant": 0}}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Dragon de lumière", "active": {"timing": "Action bonus", "uses": "1 fois par Repos au Feu", "effect": "Le personnage augmente sa Défense élémentaire de +3 pendant 5 tours. Le personnage régénère 1d6 PV par tour pendant 5 tours. Le personnage ajoute 2d6 dégâts à ses sorts une fois par tour pendant 5 tours. Une utilisation, récupérée après un repos long.", "activation": {"type": "bonus_action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.dragons.dragon-cristallin.rank-5.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.dragons.dragon-cristallin.rank-5", "capabilities": [{"id": "path.dragons.dragon-cristallin.rank-5.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_stat", "target": "selected", "stat": "defense.elemental", "value": 3, "duration": {"value": 5, "unit": "turn"}, "operation": "add"}, {"type": "modify_resource", "target": "selected", "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}, "frequency": "once_per_turn", "duration": {"value": 5, "unit": "turn"}, "resource": "health", "operation": "add"}, {"type": "damage", "target": "selected", "damage_type": "inherited", "applies_to": "spell", "value": {"dice": {"count": 2, "sides": 6}, "terms": [], "constant": 0}, "frequency": "once_per_turn", "duration": {"value": 5, "unit": "turn"}, "mode": "attach"}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 0, 0, 0, 2, 1, 0, 1, 'path.dragons.dragon-cristallin', 0, 0, 0);
