taques", "targeting": {"selector": "multiple", "allegiance": ["enemy"]}, "operations": [{"type": "extra_attack", "target": "self", "count": 3, "distribution": "multiple_targets"}]}, {"id": "distributed_damage", "label": "Dégâts répartis", "targeting": {"selector": "multiple", "allegiance": ["enemy"]}, "operations": [{"type": "damage", "target": "selected", "damage_type": "physical", "distribution": "chosen_targets", "value": {"dice": {"count": 6, "sides": 6}, "terms": [{"type": "ability_modifier", "ability": "strength"}], "constant": 0}}]}]}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 2, 1, 0, 0, 0, 0, 1, 'path.hommes-serpents.serpent-quadribrachial', 0, 0, 0);
