ois par Repos au Feu", "effect": "Nuage toxique pendant 3 tours : 1d6 Poison par tour et −1 aux trois Défenses.", "activation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.hommes-champignons.mycelien-sporifere.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.hommes-champignons.mycelien-sporifere.rank-3", "capabilities": [{"id": "path.hommes-champignons.mycelien-sporifere.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Nuage toxique pendant 3 tours : 1d6 Poison par tour et −1 aux trois Défenses."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Floraison toxique", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Relie jusqu’à quatre alliés pendant 3 tours ; les soins et dégâts peuvent être répartis entre eux.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.hommes-champignons.mycelien-sporifere.rank-4.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.hommes-champignons.mycelien-sporifere.rank-4", "capabilities": [{"id": "path.hommes-champignons.mycelien-sporifere.rank-4.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Relie jusqu’à quatre alliés pendant 3 tours ; les soins et dégâts peuvent être répartis entre eux."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Réseau universel", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Les cibles dans la zone régénère 1d6 PV par tour pendant 5 tours. Les cibles dans la zone subit 1d6 dégâts de poison pendant 5 tours. Une utilisation, récupérée après un repos long.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.hommes-champignons.mycelien-sporifere.rank-5.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.hommes-champignons.mycelien-sporifere.rank-5", "capabilities": [{"id": "path.hommes-champignons.mycelien-sporifere.rank-5.active", "support": "full", "targeting": {"selector": "all", "area": {"shape": "radius", "distance": {"value": 9, "unit": "meter"}}}, "operations": [{"type": "modify_resource", "target": "selected", "target_filter": "ally", "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}, "frequency": "once_per_turn", "duration": {"value": 5, "unit": "turn"}, "resource": "health", "operation": "add"}, {"type": "damage", "target": "selected", "target_filter": "enemy", "damage_type": "poison", "value": {"dice": {"count": 1, "sides": 6}, "terms": [], "constant": 0}, "triggers": ["each_turn"], "duration": {"value": 5, "unit": "turn"}}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 0, 0, 0, 0, 2, 1, 1, 'path.hommes-champignons.mycelien-sporifere', 0, 0, 0);
