targeting": {"selector": "self"}, "operations": [{"type": "modify_stat", "target": "selected", "stat": "initiative", "value": 3, "operation": "add"}, {"type": "damage", "target": "selected", "damage_type": "inherited", "value": {"dice": {"count": 2, "sides": 6}, "terms": [], "constant": 0}, "frequency": "first_attack", "mode": "attach"}]}]}, {"rank": 4, "name": "Déchaînement chimérique", "active": null, "passive": {"frequency": "1/tour", "effect": "Combat en meute : si un allié est adjacent à la cible, tous deux infligent +1d6 dégâts.", "automation": {"level": "partial", "effects": []}}, "id": "path.demi-humains.chimere-ferale.rank-4", "capabilities": [{"id": "path.demi-humains.chimere-ferale.rank-4.passive", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Combat en meute : si un allié est adjacent à la cible, tous deux infligent +1d6 dégâts."}]}]}, {"rank": 5, "name": "Bête parfaite", "active": {"timing": "Action bonus", "uses": "1 fois par Repos au Feu", "effect": "Forme prédatrice pendant 5 tours : cumule trois adaptations et gagne une attaque naturelle supplémentaire.", "activation": {"type": "bonus_action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.demi-humains.chimere-ferale.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.demi-humains.chimere-ferale.rank-5", "capabilities": [{"id": "path.demi-humains.chimere-ferale.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Forme prédatrice pendant 5 tours : cumule trois adaptations et gagne une attaque naturelle supplémentaire."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 1, 2, 0, 0, 0, 0, 1, 'path.demi-humains.chimere-ferale', 0, 0, 0);
INSERT INTO racial_path (id, species_id, name, abilities, ranks_json, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured, stable_key, physical_bonus, elemental_bonus, spiritual_bonus) VALUES (28, 26, 'Chimère éveillée', '+2 INT, +1 CHA', '[{"rank": 1, "name": "Conscience hybride", "active": {"timing": "Après repos long", "uses": "Permanent", "effect": "Après chaque repos long, choisissez une compétence ou un type d’outil. Jusqu’à votre prochain repos long, ajoutez +2 au résultat des tests effectués avec cette compétence ou cet outil.", "activation": {"type": "after_long_rest"}, "resource": null, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.demi-humains.chimere-eveillee.rank-1", "capabilities": [{"id": "path.demi-humains.chimere-eveillee.rank-1.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Après chaque repos long, choisissez une compétence ou un type d’outil. Jusqu’à votre prochain repos long, ajoutez +2 au résultat des tests effectués avec cette compétence ou cet outil."}]}]}, {"rank": 2, "name": "Adaptation consciente", "active": {"timing": "Réaction", "uses": "2 fois par Repos au Feu", "effect": "Lorsqu’une créature que vous voyez réussit un test de compétence ou un test effectué avec un outil, vous pouvez l’imiter. Pendant 3 tours, ajoutez +2 au résultat de vos tests avec cette même compétence ou ce même type d’outil.", "activation": {"type": "reaction"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.demi-humains.chimere-eveillee.rank-2.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.demi-humains.chimere-eveillee.rank-2", "capabilities": [{"id": "path.demi-humains.chimere-eveillee.rank-2.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Lorsqu’une créature que vous voyez réussit un test de compétence ou un test effectué avec un outil, vous pouvez l’imiter. Pendant 3 tours, ajoutez +2 au résultat de vos tests avec cette même compétence ou ce même type d’outil."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 3, "name": "Métamorphose choisie", "active": {"timing": "Après repos long", "uses": "Permanent", "effect": "Choisit +1 Défense, +3 m de vitesse, une arme naturelle ou +2 à une compétence.", "activation": {"type": "after_long_rest"}, "resource": null, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.demi-humains.chimere-eveillee.rank-3", "capabilities": [{"id": "path.demi-humains.chimere-eveillee.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Choisit +1 Défense, +3 m de vitesse, une arme naturelle ou +2 à une compétence."}]}]}, {"rank": 4, "name": "Contrôle des formes", "active": {"timing": "Réaction", "uses": "1 fois par Repos au Feu", "effect": "Copie une aptitude de rang 1 à 3 observée, utilisable une fois avant le prochain repos.", "activation": {"type": "reaction"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.demi-humains.chimere-eveillee.rank-4.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.demi-humains.chimere-eveillee.rank-4", "capabilities": [{"id": "path.demi-humains.chimere-eveillee.rank-4.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Copie une aptitude de rang 1 à 3 observée, utilisable une fois avant le prochain repos."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Ascension chimérique", "active": {"timing": "Après repos long", "uses": "Permanent", "effect": "Combine deux adaptations de rang 3 et peut les remplacer à chaque repos long.", "activation": {"type": "after_long_rest"}, "resource": null, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.demi-humains.chimere-eveillee.rank-5", "capabilities": [{"id": "path.demi-humains.chimere-eveillee.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Combine deux adaptations de rang 3 et peut les remplacer à chaque repos long."}]}]}]', 0, 0, 0, 2, 0, 1, 1, 'path.demi-humains.chimere-eveillee', 0, 0, 0);
INSERT INTO racial_path (id, species_id, name, abilities, ranks_json, strength_bonus, dexterity_bonus, constitution_bonus, intelligence_bonus, wisdom_bonus, charisma_bonus, configured, stable_key, physical_bonus, elemental_bonus, spiritual_bonus) VALUES (31, 28, 'Enfant de la Mort', '+2 CON, +1 SAG', '[{"rank": 1, "name": "Ossature maudite", "active": null, "passive": {"frequency": "Permanent", "effect": "Le personnage est immunisé contre les maladies ordinaires. Le personnage est immunisé contre les poisons ordinaires.", "automation": {"level": "full", "effects": []}}, "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-1", "capabilities": [{"id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-1.passive", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_protection", "target": "selected", "status": "ordinary_disease"}, {"type": "modify_protection", "target": "selected", "status": "ordinary_poison"}]}]}, {"rank": 2, "name": "Rappel des os", "active": {"timing": "Réaction", "uses": "2 fois par Repos au Feu", "effect": "Le personnage récupère 2d8 + modificateur de Constitution PV. 2 utilisations, récupérées après un repos long.", "activation": {"type": "reaction"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-2.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-2", "capabilities": [{"id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-2.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_resource", "target": "selected", "value": {"dice": {"count": 2, "sides": 8}, "terms": [{"type": "ability_modifier", "ability": "constitution"}], "constant": 0}, "resource": "health", "operation": "add"}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 3, "name": "Carapace funèbre", "active": {"timing": "Action", "uses": "2 fois par Repos au Feu", "effect": "Anime un cadavre pendant 3 tours : 15 PV et attaque de 2d6 dégâts.", "activation": {"type": "action"}, "resource": {"maximum": 2, "cost": 1, "recovery": ["long_rest"], "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-3.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-3", "capabilities": [{"id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-3.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Anime un cadavre pendant 3 tours : 15 PV et attaque de 2d6 dégâts."}], "uses": {"maximum": 2, "recharge": "long_rest"}}]}, {"rank": 4, "name": "Marche du tombeau", "active": {"timing": "Réaction", "uses": "1 fois par Repos au Feu", "effect": "Le personnage reste à au moins 1 PV au lieu de tomber à 0 PV. Le personnage augmente sa Défense physique de +2 pendant 3 tours. Une utilisation, récupérée après un repos long.", "activation": {"type": "reaction"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-4.uses"}, "automation": {"level": "full", "effects": []}}, "passive": null, "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-4", "capabilities": [{"id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-4.active", "support": "full", "targeting": {"selector": "self"}, "operations": [{"type": "modify_resource", "target": "selected", "value": 1, "resource": "health", "operation": "set_minimum"}, {"type": "modify_stat", "target": "selected", "stat": "defense.physical", "value": 2, "duration": {"value": 3, "unit": "turn"}, "operation": "add"}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}, {"rank": 5, "name": "Éternel ossuaire", "active": {"timing": "Action", "uses": "1 fois par Repos au Feu", "effect": "Anime jusqu’à trois cadavres pendant 5 tours, ou ressuscite temporairement un allié avec la moitié de ses PV.", "activation": {"type": "action"}, "resource": {"maximum": 1, "cost": 1, "recovery": ["long_rest"], "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-5.uses"}, "automation": {"level": "partial", "effects": []}}, "passive": null, "id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-5", "capabilities": [{"id": "path.enfant-des-tenebres.enfant-de-la-mort.rank-5.active", "support": "partial", "targeting": {"selector": "self"}, "operations": [{"type": "custom_ability", "target": "self", "description": "Anime jusqu’à trois cadavres pendant 5 tours, ou ressuscite temporairement un allié avec la moitié de ses PV."}], "uses": {"maximum": 1, "recharge": "long_rest"}}]}]', 0, 0, 2, 0, 1, 0, 1, 'path.enfant-des-tenebres.enfant-de-la-mort', -2, 0, 2);
