INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9595, 1, 1, 'Garde solidaire', 'passive', 'partial', NULL, 'Permanent', 'Avec un bouclier, gagne +1 Défense physique. Un allié adjacent gagne également +1 Défense physique.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9596, 1, 2, 'Interposition', 'active', 'full', 'reaction', NULL, '', 3, 'short_rest', '{"selector": "single", "allegiance": ["ally"], "range": {"value": 3, "unit": "meter"}}', '{"resource_id": "path.chevalier.rempart.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9597, 1, 3, 'Cercle protecteur', 'active', 'full', 'bonus_action', NULL, '', 2, 'short_rest', '{"selector": "all", "allegiance": ["ally"], "include_self": true, "area": {"shape": "radius", "distance": {"value": 3, "unit": "meter"}}}', '{"resource_id": "path.chevalier.rempart.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9598, 1, 4, 'Égide du martyr', 'active', 'partial', 'reaction', NULL, 'Lorsqu’un allié situé à 6 m ou moins est ciblé par une attaque, vous devenez la cible à sa place. Vous gagnez +3 en Défense physique, élémentaire et spirituelle uniquement contre cette attaque.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.chevalier.rempart.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9599, 1, 5, 'Forteresse vivante', 'active', 'partial', 'action', NULL, 'Pendant 5 tours, vous gagnez +3 en Défense physique et +2 en Défense élémentaire et spirituelle. Lorsqu’un allié situé à 6 m ou moins subit des dégâts après application de sa Défense, il n’en subit que la moitié et vous perdez autant de PV que les dégâts évités.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.chevalier.rempart.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9600, 2, 1, 'Fureur écarlate', 'active', 'full', 'bonus_action', NULL, '', 2, 'short_rest', '{"selector": "self"}', '{"resource_id": "path.chevalier.berserker.rank-1.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9601, 2, 2, 'Offrande de sang', 'active', 'full', 'free', NULL, '', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.chevalier.berserker.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9602, 2, 3, 'Refus de mourir', 'active', 'full', 'reaction', NULL, '', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.chevalier.berserker.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9603, 2, 4, 'Tourbillon carnassier', 'active', 'partial', 'action', NULL, 'Attaque tous les ennemis adjacents : dégâts de l’arme +2d6, puis perd 2d6 PV.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.chevalier.berserker.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9604, 2, 5, 'Rage sans fin', 'active', 'partial', 'bonus_action', NULL, 'Pendant 5 tours : une attaque supplémentaire, +2d6 dégâts une fois par tour, −3 aux trois Défenses et perte de 1d8 PV par tour.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.chevalier.berserker.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9605, 3, 1, 'Pas de l’ombre', 'passive', 'partial', NULL, 'Permanent', 'Ajoutez +2 au résultat de vos tests de Discrétion, Tromperie et Escamotage, ainsi qu’aux tests effectués avec des outils de voleur. Vous pouvez effectuer l’action Se cacher avec une action bonus.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9606, 3, 2, 'Frappe déloyale', 'passive', 'partial', NULL, '1/tour', 'Une attaque contre une cible surprise, distraite ou engagée par un allié inflige +2d6 dégâts.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9607, 3, 3, 'Feinte fatale', 'active', 'partial', 'bonus_action', NULL, 'Feinte : la cible perd 2 Défense physique et la prochaine attaque du Voleur devient critique.', 2, 'short_rest', '{"selector": "self"}', '{"resource_id": "path.roublard.voleur.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9608, 3, 4, 'Évanescence', 'passive', 'partial', NULL, '1/tour', 'Après une attaque furtive ou critique, se déplace de 3 m sans réaction ennemie et peut se cacher.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9609, 3, 5, 'Assassinat parfait', 'active', 'partial', 'free', NULL, 'Une attaque devient critique, inflige +4d6 dégâts, puis le Voleur devient invisible jusqu’au début de son prochain tour.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.roublard.voleur.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9610, 4, 1, 'Œil du tireur', 'passive', 'partial', NULL, 'Permanent', 'Lorsque vous infligez des dégâts avec un arc, une arbalète ou un pistolet, ajoutez +2 aux dégâts. Ajoutez également +2 au résultat de vos tests de Perception pour observer une cible éloignée. Recharger une arbalète ou un pistolet nécessite une action bonus.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9611, 4, 2, 'Visée lointaine', 'passive', 'partial', NULL, 'Permanent', 'Double la portée normale et ignore les couverts légers ainsi que 1 Défense physique.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9612, 4, 3, 'Double détente', 'active', 'full', 'action', NULL, '', 2, 'short_rest', '{"selector": "self"}', '{"resource_id": "path.roublard.archer.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9613, 4, 4, 'Trait perforant', 'active', 'partial', 'action', NULL, 'Tir perforant : dégâts de l’arme +3d6, traverse une ligne de 9 m et ignore 2 Défense physique.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.roublard.archer.rank-4.uses"}');
