INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9615, 5, 1, 'Note inspirante', 'active', 'partial', 'reaction', NULL, 'Choisissez un allié situé à 9 m ou moins. Il ajoute 1d6 au résultat d’une sauvegarde ou d’un test de compétence qu’il vient d’effectuer.', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.heraut.barde.rank-1.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9616, 5, 2, 'Refrain réconfortant', 'active', 'full', 'action', NULL, '', 2, 'short_rest', '{"selector": "all", "allegiance": ["ally"], "include_self": true, "area": {"shape": "radius", "distance": {"value": 6, "unit": "meter"}}}', '{"resource_id": "path.heraut.barde.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9617, 5, 3, 'Discordance', 'active', 'partial', 'action', NULL, 'Chaque ennemi situé à 6 m ou moins effectue une sauvegarde de Sagesse. En cas d’échec, il inflige 2 dégâts de moins et subit −1 en Défense physique, élémentaire et spirituelle pendant 3 tours. Une réussite annule ces effets.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.heraut.barde.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9618, 5, 4, 'Symphonie guerrière', 'active', 'full', 'bonus_action', NULL, '', 1, 'long_rest', '{"selector": "all", "allegiance": ["ally"], "include_self": false, "area": {"shape": "radius", "distance": {"value": 6, "unit": "meter"}}}', '{"resource_id": "path.heraut.barde.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9619, 5, 5, 'Chant des légendes', 'active', 'partial', 'action', NULL, 'Chant épique pendant 5 tours : alliés +2 aux trois Défenses, +2d6 dégâts une fois par tour et déplacement gratuit de 3 m.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.heraut.barde.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9620, 6, 1, 'Langue d’argent', 'passive', 'partial', NULL, 'Permanent', 'Ajoutez +3 au résultat de vos tests de Persuasion, Intimidation et Intuition.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9621, 6, 2, 'Parole terrifiante', 'active', 'partial', 'action', NULL, 'Choisissez une créature située à 9 m ou moins. Elle effectue une sauvegarde de Sagesse. En cas d’échec, elle est Effrayée et inflige 2 dégâts de moins pendant 2 tours. Une réussite annule ces effets.', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.heraut.diplomate.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9622, 6, 3, 'Ordre impérieux', 'active', 'partial', 'bonus_action', NULL, 'Choisissez un allié situé à 9 m ou moins. Il peut immédiatement utiliser sa réaction pour se déplacer de 6 m au maximum ou effectuer une attaque.', 2, 'short_rest', '{"selector": "self"}', '{"resource_id": "path.heraut.diplomate.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9623, 6, 4, 'Décret protecteur', 'active', 'partial', 'reaction', NULL, 'Lorsqu’une attaque touche un allié situé à 9 m ou moins, réduisez les dégâts qu’il subit de 2d8 + MOD Charisme.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.heraut.diplomate.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9624, 6, 5, 'Présence souveraine', 'active', 'partial', 'action', NULL, 'Aura souveraine de 9 m pendant 5 tours : les ennemis ratant une sauvegarde de Sagesse subissent −2 dégâts et −2 aux trois Défenses.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.heraut.diplomate.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9625, 7, 1, 'Main experte', 'active', 'partial', 'action', NULL, '', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9626, 7, 1, 'Main experte', 'passive', 'partial', NULL, 'Permanent', 'Tests réalisés avec des outils : +3 au dé.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9627, 7, 2, 'Piège incendiaire', 'active', 'partial', 'action', NULL, 'Posez un piège. Lorsqu’il se déclenche, chaque créature située dans un rayon de 2 m subit 3d6 dégâts physiques ou de Feu, au choix lors de la pose. Une créature qui réussit une sauvegarde de Dextérité ne subit que la moitié des dégâts.', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.ingenieur.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9628, 7, 3, 'Surcharge élémentaire', 'active', 'full', 'bonus_action', NULL, '', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.ingenieur.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9629, 7, 4, 'Artillerie portative', 'active', 'partial', 'action', NULL, 'Déployez un canon et choisissez une ligne de 12 m ou un cône de 6 m. Chaque créature dans la zone subit 6d6 dégâts élémentaires. Une créature qui réussit une sauvegarde de Dextérité ne subit que la moitié des dégâts.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.ingenieur.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9630, 7, 5, 'Chef-d’œuvre mécanique', 'active', 'partial', 'action', NULL, 'Déploie un automate pendant 5 tours : 30 PV, Défenses 6/6/4 et 3d6 + MOD Intelligence dégâts par tour.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.ingenieur.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9631, 8, 1, 'Instinct des pistes', 'passive', 'partial', NULL, 'Permanent', 'Ajoutez +3 au résultat de vos tests de Survie, Perception et Pistage. Les terrains difficiles d’origine naturelle ne vous coûtent aucun déplacement supplémentaire.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9632, 8, 2, 'Havre du voyageur', 'active', 'partial', 'special', NULL, 'Construit un campement : au prochain repos, chaque allié récupère +2d8 PV et gagne 1d8 PV temporaires.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.survivaliste.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9633, 8, 3, 'Lecture de la proie', 'active', 'partial', 'bonus_action', NULL, 'Analyse une cible pendant 3 tours : révèle ses Défenses et le groupe ignore 2 points d’une Défense choisie, une fois par tour.', 2, 'short_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.survivaliste.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9634, 8, 4, 'Adaptation collective', 'active', 'partial', 'action', NULL, 'Pendant 5 tours, le groupe choisit : +3 Défense contre un élément, camouflage ou +3 m de vitesse.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.survivaliste.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9635, 8, 5, 'Traque inexorable', 'active', 'partial', 'bonus_action', NULL, 'Marque une cible pendant 5 tours : elle ne peut se cacher, le groupe ignore la moitié d’une Défense et inflige +2d6 dégâts une fois par tour.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.specialiste.survivaliste.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9636, 9, 1, 'Imposition sacrée', 'active', 'full', 'action', NULL, '', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.pretre.rank-1.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9637, 9, 2, 'Foudre illusoire', 'active', 'full', 'special', NULL, '', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.pretre.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9638, 9, 3, 'Grâce partagée', 'active', 'full', 'action', NULL, '', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.pretre.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9639, 9, 4, 'Tempête des simulacres', 'active', 'partial', 'action', NULL, 'Choisit une tempête de 5d6 + MOD Sagesse Foudre dans un rayon de 4 m ou trois doubles illusoires absorbant chacun une attaque.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.pretre.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9640, 9, 5, 'Miracle divin', 'active', 'partial', 'action', NULL, 'Miracle : soin collectif de 6d8 + MOD Sagesse, résurrection avec la moitié des PV, ou tempête de 6d6 + MOD Sagesse.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.pretre.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9641, 10, 1, 'Murmure interdit', 'active', 'partial', 'free', NULL, 'Dépense une Humanité pour ajouter +2d6 Ténèbres, récupérer 2d6 PV ou gagner +2 Défense spirituelle pendant un tour.', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.occultiste.rank-1.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9642, 10, 2, 'Sceau corrupteur', 'active', 'partial', 'action', NULL, 'Inflige 3d6 + MOD Sagesse Ténèbres et récupère la moitié des dégâts réellement infligés.', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.occultiste.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9643, 10, 3, 'Moisson d’âmes', 'active', 'partial', 'action', NULL, 'Anime un cadavre pendant 5 tours : 20 PV, Défenses 4/2/4 et attaque de 2d6 + MOD Sagesse.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.occultiste.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9644, 10, 4, 'Rituel du néant', 'active', 'partial', 'bonus_action', NULL, 'Forme d’Humanité pendant 5 tours : +2 Défense spirituelle, drain de 1d6 PV par tour et reste à 1 PV la première fois qu’il tombe à 0.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.occultiste.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9645, 10, 5, 'Pacte ultime', 'active', 'partial', 'action', NULL, 'Chaque ennemi situé dans un rayon de 6 m subit 5d6 dégâts de Ténèbres. Une sauvegarde de Sagesse réussie réduit ces dégâts de moitié. Choisissez ensuite un seul effet : vous récupérez un nombre de PV égal au total des dégâts infligés, avec un maximum de 5d6 PV, ou vous animez jusqu’à trois cadavres.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.clerc.occultiste.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9646, 11, 1, 'Morsure du givre', 'active', 'full', 'action', NULL, '', 3, 'long_rest', '{"selector": "single", "allegiance": ["enemy"]}', '{"resource_id": "path.sorcier.cryomancien.rank-1.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9647, 11, 2, 'Miroir de givre', 'active', 'full', 'reaction', NULL, '', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.sorcier.cryomancien.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9648, 11, 2, 'Miroir de givre', 'passive', 'partial', NULL, 'À volonté', 'Vous pouvez façonner un petit objet utilitaire en glace, comme une clé simple, un récipient ou un outil. L’objet fond lorsque vous le décidez ou au prochain Repos au Feu et ne peut pas servir d’arme.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9649, 11, 3, 'Prison de glace', 'active', 'partial', 'action', NULL, 'Choisissez un seul effet : créer un mur de glace possédant 25 PV ; ou enfermer une cible dans une prison de glace. La cible effectue une sauvegarde de Force : en cas d’échec, elle est Immobilisée pendant 3 tours et subit 1d6 dégâts de Glace au début de chacun de ses tours ; en cas de réussite, la prison ne se forme pas.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.sorcier.cryomancien.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9650, 11, 4, 'Blizzard blanc', 'active', 'partial', 'action', NULL, 'Créez un blizzard dans un rayon de 6 m. Chaque créature dans la zone subit 5d6 + MOD Intelligence dégâts de Glace. Une sauvegarde de Dextérité réussie réduit ces dégâts de moitié. La zone devient un terrain difficile pendant 3 tours : chaque mètre parcouru y coûte 2 m de déplacement.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.sorcier.cryomancien.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9651, 11, 5, 'Zéro absolu', 'active', 'full', 'action', NULL, '', 1, 'long_rest', '{"selector": "all", "area": {"shape": "radius", "distance": {"value": 6, "unit": "meter"}}}', '{"resource_id": "path.sorcier.cryomancien.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9652, 12, 1, 'Savoir méthodique', 'active', 'full', 'action', NULL, '', 3, 'long_rest', '{"selector": "single", "allegiance": ["enemy"]}', '{"resource_id": "path.sorcier.chercheur.rank-1.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9653, 12, 1, 'Savoir méthodique', 'passive', 'partial', NULL, 'Permanent', 'Tests d’Intelligence pour les Arcanes et la Recherche : +3 au dé.', NULL, NULL, '{"selector": "self"}', NULL);
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9654, 12, 2, 'Analyse arcanique', 'active', 'partial', 'action', NULL, 'Crée un leurre de 10 PV pendant 3 tours, ou analyse complètement un effet magique.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.sorcier.chercheur.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9655, 12, 3, 'Contre-mesure', 'active', 'partial', 'free', NULL, 'Lorsque vous lancez un sort, choisissez une seule amélioration : ajouter 2d6 à ses dégâts ; augmenter de 3 m le rayon, la longueur ou la portée de sa zone ; changer son type de dégâts ; ou ignorer 2 points de Défense élémentaire des cibles.', 3, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.sorcier.chercheur.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9656, 12, 4, 'Théorie accomplie', 'active', 'partial', 'reaction', NULL, 'Annule un sort visible et peut le relancer gratuitement avant la fin de son prochain tour.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.sorcier.chercheur.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9657, 12, 5, 'Révélation suprême', 'active', 'partial', 'action', NULL, 'Grande découverte : 8d6 + MOD Intelligence sur une cible, 6d6 + MOD Intelligence dans une zone, ou duplication de deux sorts de rangs 1 à 3.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.sorcier.chercheur.rank-5.uses"}');
