INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9660, 13, 3, 'Déferlement ardent', 'active', 'full', 'action', NULL, '', 2, 'long_rest', '{"selector": "all", "allegiance": ["enemy"], "area": {"shape": "radius", "distance": {"value": 3, "unit": "meter"}}}', '{"resource_id": "path.pyromancien.adepte-du-chaos.rank-3.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9661, 13, 4, 'Brasier instable', 'active', 'partial', 'action', NULL, 'Chaque créature située dans un rayon de 4 m subit 6d6 + MOD Sagesse dégâts de Feu. Une sauvegarde de Dextérité réussie réduit ces dégâts de moitié. La zone reste couverte de lave pendant 2 tours.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.pyromancien.adepte-du-chaos.rank-4.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9662, 13, 5, 'Soleil du Chaos', 'active', 'partial', 'action', NULL, 'Tempête pendant 5 tours : zone de 6 m, 3d6 Feu par tour ; les alliés choisis gagnent +1d6 Feu une fois par tour.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.pyromancien.adepte-du-chaos.rank-5.uses"}');
