INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9664, 14, 2, 'Souillure ardente', 'active', 'partial', 'action', NULL, 'Perd 2d6 PV, inflige 5d6 + MOD Sagesse Ténèbres et récupère la moitié des dégâts réellement infligés.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.pyromancien.profane.rank-2.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9665, 14, 3, 'Cendre maudite', 'active', 'partial', 'action', NULL, 'Perd 2d8 PV, inflige 4d6 Ténèbres et brûle une émotion pendant 3 tours si la sauvegarde de Sagesse échoue.', 2, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.pyromancien.profane.rank-3.uses"}');
