INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9667, 14, 5, 'Éclipse incendiaire', 'active', 'partial', 'action', NULL, 'Tombe à 1 PV et inflige 10d6 + MOD Sagesse. Sagesse ratée : un concept simple est supprimé pendant 5 tours ; réussite : moitié des dégâts seulement.', 1, 'long_rest', '{"selector": "self"}', '{"resource_id": "path.pyromancien.profane.rank-5.uses"}');
INSERT INTO path_rank_definition (id, path_definition_id, rank, name, mode, support, activation, frequency, effect_manual, uses_maximum, recharge, targeting_json, trigger_json) VALUES (9668, 15, 1, 'Héritage solaire', 'passive', 'partial', NULL, 'Permanent', 'Vous pouvez produire une lumière à volonté. Ajoutez +2 au résultat des tests sociaux servant à donner un ordre, imposer votre autorité ou impressionner par votre statut.', NULL, NULL, '{"selector": "self"}', NULL);
