INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13160, 9598, 0, 'custom_ability', 'self', '{"description": "Lorsqu’un allié situé à 6 m ou moins est ciblé par une attaque, vous devenez la cible à sa place. Vous gagnez +3 en Défense physique, élémentaire et spirituelle uniquement contre cette attaque."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13161, 9599, 0, 'custom_ability', 'self', '{"description": "Pendant 5 tours, vous gagnez +3 en Défense physique et +2 en Défense élémentaire et spirituelle. Lorsqu’un allié situé à 6 m ou moins subit des dégâts après application de sa Défense, il n’en subit que la moitié et vous perdez autant de PV que les dégâts évités."}', 1);
