INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13170, 9603, 0, 'custom_ability', 'self', '{"description": "Attaque tous les ennemis adjacents : dégâts de l’arme +2d6, puis perd 2d6 PV."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13171, 9604, 0, 'custom_ability', 'self', '{"description": "Pendant 5 tours : une attaque supplémentaire, +2d6 dégâts une fois par tour, −3 aux trois Défenses et perte de 1d8 PV par tour."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13172, 9605, 0, 'custom_ability', 'self', '{"description": "Ajoutez +2 au résultat de vos tests de Discrétion, Tromperie et Escamotage, ainsi qu’aux tests effectués avec des outils de voleur. Vous pouvez effectuer l’action Se cacher avec une action bonus."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13173, 9606, 0, 'custom_ability', 'self', '{"description": "Une attaque contre une cible surprise, distraite ou engagée par un allié inflige +2d6 dégâts."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13174, 9607, 0, 'custom_ability', 'self', '{"description": "Feinte : la cible perd 2 Défense physique et la prochaine attaque du Voleur devient critique."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13175, 9608, 0, 'custom_ability', 'self', '{"description": "Après une attaque furtive ou critique, se déplace de 3 m sans réaction ennemie et peut se cacher."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13176, 9609, 0, 'custom_ability', 'self', '{"description": "Une attaque devient critique, inflige +4d6 dégâts, puis le Voleur devient invisible jusqu’au début de son prochain tour."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13177, 9610, 0, 'custom_ability', 'self', '{"description": "Lorsque vous infligez des dégâts avec un arc, une arbalète ou un pistolet, ajoutez +2 aux dégâts. Ajoutez également +2 au résultat de vos tests de Perception pour observer une cible éloignée. Recharger une arbalète ou un pistolet nécessite une action bonus."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13178, 9611, 0, 'custom_ability', 'self', '{"description": "Double la portée normale et ignore les couverts légers ainsi que 1 Défense physique."}', 1);
