INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13192, 9621, 0, 'custom_ability', 'self', '{"description": "Choisissez une créature située à 9 m ou moins. Elle effectue une sauvegarde de Sagesse. En cas d’échec, elle est Effrayée et inflige 2 dégâts de moins pendant 2 tours. Une réussite annule ces effets."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13193, 9622, 0, 'custom_ability', 'self', '{"description": "Choisissez un allié situé à 9 m ou moins. Il peut immédiatement utiliser sa réaction pour se déplacer de 6 m au maximum ou effectuer une attaque."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13194, 9623, 0, 'custom_ability', 'self', '{"description": "Lorsqu’une attaque touche un allié situé à 9 m ou moins, réduisez les dégâts qu’il subit de 2d8 + MOD Charisme."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13195, 9624, 0, 'custom_ability', 'self', '{"description": "Aura souveraine de 9 m pendant 5 tours : les ennemis ratant une sauvegarde de Sagesse subissent −2 dégâts et −2 aux trois Défenses."}', 1);
