INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13200, 9629, 0, 'custom_ability', 'self', '{"description": "Déployez un canon et choisissez une ligne de 12 m ou un cône de 6 m. Chaque créature dans la zone subit 6d6 dégâts élémentaires. Une créature qui réussit une sauvegarde de Dextérité ne subit que la moitié des dégâts."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13201, 9630, 0, 'custom_ability', 'self', '{"description": "Déploie un automate pendant 5 tours : 30 PV, Défenses 6/6/4 et 3d6 + MOD Intelligence dégâts par tour."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13202, 9631, 0, 'custom_ability', 'self', '{"description": "Ajoutez +3 au résultat de vos tests de Survie, Perception et Pistage. Les terrains difficiles d’origine naturelle ne vous coûtent aucun déplacement supplémentaire."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13203, 9632, 0, 'custom_ability', 'self', '{"description": "Construit un campement : au prochain repos, chaque allié récupère +2d8 PV et gagne 1d8 PV temporaires."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13204, 9633, 0, 'custom_ability', 'self', '{"description": "Analyse une cible pendant 3 tours : révèle ses Défenses et le groupe ignore 2 points d’une Défense choisie, une fois par tour."}', 1);
