INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13211, 9640, 0, 'custom_ability', 'self', '{"description": "Miracle : soin collectif de 6d8 + MOD Sagesse, résurrection avec la moitié des PV, ou tempête de 6d6 + MOD Sagesse."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13212, 9641, 0, 'custom_ability', 'self', '{"description": "Dépense une Humanité pour ajouter +2d6 Ténèbres, récupérer 2d6 PV ou gagner +2 Défense spirituelle pendant un tour."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13213, 9642, 0, 'custom_ability', 'self', '{"description": "Inflige 3d6 + MOD Sagesse Ténèbres et récupère la moitié des dégâts réellement infligés."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13214, 9643, 0, 'custom_ability', 'self', '{"description": "Anime un cadavre pendant 5 tours : 20 PV, Défenses 4/2/4 et attaque de 2d6 + MOD Sagesse."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13215, 9644, 0, 'custom_ability', 'self', '{"description": "Forme d’Humanité pendant 5 tours : +2 Défense spirituelle, drain de 1d6 PV par tour et reste à 1 PV la première fois qu’il tombe à 0."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13216, 9645, 0, 'custom_ability', 'self', '{"description": "Chaque ennemi situé dans un rayon de 6 m subit 5d6 dégâts de Ténèbres. Une sauvegarde de Sagesse réussie réduit ces dégâts de moitié. Choisissez ensuite un seul effet : vous récupérez un nombre de PV égal au total des dégâts infligés, avec un maximum de 5d6 PV, ou vous animez jusqu’à trois cadavres."}', 1);
