INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13220, 9648, 0, 'custom_ability', 'self', '{"description": "Vous pouvez façonner un petit objet utilitaire en glace, comme une clé simple, un récipient ou un outil. L’objet fond lorsque vous le décidez ou au prochain Repos au Feu et ne peut pas servir d’arme."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13221, 9649, 0, 'custom_ability', 'self', '{"description": "Choisissez un seul effet : créer un mur de glace possédant 25 PV ; ou enfermer une cible dans une prison de glace. La cible effectue une sauvegarde de Force : en cas d’échec, elle est Immobilisée pendant 3 tours et subit 1d6 dégâts de Glace au début de chacun de ses tours ; en cas de réussite, la prison ne se forme pas."}', 1);
INSERT INTO path_operation (id, rank_definition_id, position, operation_type, target, parameters_json, enabled) VALUES (13222, 9650, 0, 'custom_ability', 'self', '{"description": "Créez un blizzard dans un rayon de 6 m. Chaque créature dans la zone subit 5d6 + MOD Intelligence dégâts de Glace. Une sauvegarde de Dextérité réussie réduit ces dégâts de moitié. La zone devient un terrain difficile pendant 3 tours : chaque mètre parcouru y coûte 2 m de déplacement."}', 1);
