INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,0,'extra_attack','self','{"count":1,"duration":{"value":5,"unit":"turn"}}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.berserker') AND rank=5;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,1,'damage','self','{"damage_type":"physical","mode":"attach","frequency":"once_per_turn","value":{"dice":[{"count":2,"sides":6}],"terms":[],"constant":0},"duration":{"value":5,"unit":"turn"}}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.berserker') AND rank=5;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,2,'modify_stat','self','{"stat":"defense.physical","operation":"add","value":-3,"duration":{"value":5,"unit":"turn"}}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.berserker') AND rank=5;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,3,'modify_stat','self','{"stat":"defense.elemental","operation":"add","value":-3,"duration":{"value":5,"unit":"turn"}}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.berserker') AND rank=5;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,4,'modify_stat','self','{"stat":"defense.spiritual","operation":"add","value":-3,"duration":{"value":5,"unit":"turn"}}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.berserker') AND rank=5;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,5,'modify_resource','self','{"resource":"health","operation":"subtract","frequency":"once_per_turn","value":{"dice":[{"count":1,"sides":8}],"terms":[],"constant":0},"duration":{"value":5,"unit":"turn"}}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.berserker') AND rank=5;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,0,'modify_stat','self','{"stat":"defense.physical","operation":"add","value":1,"condition":{"type":"shield_equipped"}}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.rempart') AND rank=1;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,1,'custom_ability','self','{"description":"Un allié adjacent gagne également +1 en Défense physique."}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.rempart') AND rank=1;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,0,'custom_ability','self','{"description":"Lorsqu’un allié situé à 6 m ou moins est ciblé par une attaque, le personnage devient la cible à sa place."}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.rempart') AND rank=4;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,position,'modify_stat','self',json_object('stat',stat,'operation','add','value',3,'condition',json_object('type','incoming_attack')) FROM path_rank_definition CROSS JOIN (SELECT 1 position,'defense.physical' stat UNION ALL SELECT 2,'defense.elemental' UNION ALL SELECT 3,'defense.spiritual') WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.rempart') AND rank=4;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,position,'modify_stat','self',json_object('stat',stat,'operation','add','value',bonus,'duration',json_object('value',5,'unit','turn')) FROM path_rank_definition CROSS JOIN (SELECT 0 position,'defense.physical' stat,3 bonus UNION ALL SELECT 1,'defense.elemental',2 UNION ALL SELECT 2,'defense.spiritual',2) WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.rempart') AND rank=5;
INSERT INTO path_operation (rank_definition_id,position,operation_type,target,parameters_json) SELECT id,3,'custom_ability','self','{"description":"Lorsqu’un allié situé à 6 m ou moins subit des dégâts après sa Défense, il n’en subit que la moitié et le personnage perd autant de PV que les dégâts évités."}' FROM path_rank_definition WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.rempart') AND rank=5;
