PRAGMA foreign_keys = ON;
BEGIN IMMEDIATE;
-- Capacités structurées du Chevalier : les parties mécaniques restent modifiables dans l’éditeur.
UPDATE path_operation SET parameters_json = '{"operation":"set_minimum","resource":"health","value":{"dice":[],"terms":[],"constant":1}}'
WHERE operation_type='modify_resource' AND rank_definition_id = (SELECT pr.id FROM path_rank_definition pr JOIN path_definition pd ON pd.id=pr.path_definition_id WHERE pd.stable_key='path.chevalier.berserker' AND pr.rank=3);

UPDATE path_rank_definition SET support='full', effect_manual=''
WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.berserker') AND rank=5;
DELETE FROM path_operation WHERE rank_definition_id=(SELECT pr.id FROM path_rank_definition pr JOIN path_definition pd ON pd.id=pr.path_definition_id WHERE pd.stable_key='path.chevalier.berserker' AND pr.rank=5);

DELETE FROM path_operation WHERE rank_definition_id IN (SELECT pr.id FROM path_rank_definition pr JOIN path_definition pd ON pd.id=pr.path_definition_id WHERE pd.stable_key='path.chevalier.rempart' AND pr.rank IN (1,4,5));
UPDATE path_rank_definition SET effect_manual='Pendant 5 tours, le personnage augmente sa Défense physique de +3 et ses Défenses élémentaire et spirituelle de +2. Lorsqu’un allié situé à 6 m ou moins subit des dégâts après sa Défense, cet allié n’en subit que la moitié. Le personnage perd alors un nombre de PV égal aux dégâts ainsi évités.' WHERE path_definition_id=(SELECT id FROM path_definition WHERE stable_key='path.chevalier.rempart') AND rank=5;
COMMIT;
